// ─────────────────────────────────────────────────────────────────────────────
// Config & Safety Gate
// Reads every runtime setting from environment variables and derives the
// hard safety gates used by every downstream IF node.
// SAFE-BY-DEFAULT: a missing, blank or unrecognised flag resolves to its safe
// value, so a fresh import performs zero external mutations.
// Secrets are NEVER copied into the item: only boolean "is present" checks.
// ─────────────────────────────────────────────────────────────────────────────
let envAccessible = true;
try { void $env.SANDBOX_MODE; } catch (e) { envAccessible = false; }

const readEnv = (key) => {
  if (!envAccessible) return undefined;
  try {
    const v = $env[key];
    return v === undefined || v === null ? undefined : String(v).trim();
  } catch (e) {
    return undefined;
  }
};

const warnings = [];
if (!envAccessible) {
  warnings.push('Environment access is blocked (N8N_BLOCK_ENV_ACCESS_IN_NODE=true). All safe defaults were applied.');
}

const flag = (key, safeDefault) => {
  const raw = readEnv(key);
  if (raw === undefined || raw === '') return safeDefault;
  const v = raw.toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  warnings.push(`${key} has an unrecognised value; using safe default (${safeDefault}).`);
  return safeDefault;
};

const num = (key, def, min, max) => {
  const raw = readEnv(key);
  if (raw === undefined || raw === '') return def;
  const n = Number(raw);
  if (!Number.isFinite(n) || n < min || n > max) {
    warnings.push(`${key} must be a number between ${min} and ${max}; using default ${def}.`);
    return def;
  }
  return n;
};

const oneOf = (key, def, allowed) => {
  const raw = (readEnv(key) || '').toLowerCase();
  if (!raw) return def;
  if (allowed.includes(raw)) return raw;
  warnings.push(`${key} must be one of ${allowed.join(', ')}; using default ${def}.`);
  return def;
};

const parseJsonEnv = (key, fallback) => {
  const raw = readEnv(key);
  if (!raw) return fallback;
  try { return JSON.parse(raw); } catch (e) {
    warnings.push(`${key} is not valid JSON; ignored.`);
    return fallback;
  }
};

// ── Run clock (RUN_TIMESTAMP_OVERRIDE allows reproducible backfills/simulations)
let runDate = new Date();
const tsOverride = readEnv('RUN_TIMESTAMP_OVERRIDE');
if (tsOverride) {
  const d = new Date(tsOverride);
  if (Number.isNaN(d.getTime())) warnings.push('RUN_TIMESTAMP_OVERRIDE is not a valid ISO date; using current time.');
  else runDate = d;
}
const isoWeek = (d) => {
  const date = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const day = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  const week = Math.ceil(((date - yearStart) / 86400000 + 1) / 7);
  return `${date.getUTCFullYear()}-W${String(week).padStart(2, '0')}`;
};

// ── Safety flags (safe defaults)
const sandboxRequested = flag('SANDBOX_MODE', true);
const dryRun = flag('DRY_RUN', true);
const hubspotLoggingEnabled = flag('HUBSPOT_LOGGING_ENABLED', false);
const sendSlackAlerts = flag('SEND_SLACK_ALERTS', false);
const sendOpsAlerts = flag('SEND_OPS_ALERTS', false);

// ── Secret presence (values are never read into the item)
const hasHubspotToken = Boolean(readEnv('HUBSPOT_ACCESS_TOKEN'));
const hasApifyToken = Boolean(readEnv('APIFY_API_TOKEN'));
const hasSlackWebhook = /^https:\/\//i.test(readEnv('SLACK_PRICING_ALERT_WEBHOOK_URL') || '');
const hasAlertWebhook = /^https:\/\//i.test(readEnv('ALERT_WEBHOOK_URL') || '');

// ── Competitor targets (live mode only)
const rawTargets = parseJsonEnv('COMPETITOR_TARGETS_JSON', []);
const competitorTargets = [];
if (!Array.isArray(rawTargets)) {
  warnings.push('COMPETITOR_TARGETS_JSON must be a JSON array; ignored.');
} else {
  const seen = new Set();
  rawTargets.forEach((t, i) => {
    const key = String(t?.competitorKey || '').trim().toLowerCase();
    const url = String(t?.pricingUrl || '').trim();
    if (!/^[a-z0-9][a-z0-9-]{1,62}$/.test(key)) { warnings.push(`Target #${i + 1} skipped: competitorKey must be a lowercase slug.`); return; }
    if (!/^https:\/\/[^\s]+$/i.test(url)) { warnings.push(`Target "${key}" skipped: pricingUrl must be an https:// URL.`); return; }
    if (seen.has(key)) { warnings.push(`Target "${key}" skipped: duplicate competitorKey.`); return; }
    seen.add(key);
    competitorTargets.push({
      competitorKey: key,
      competitorName: String(t.competitorName || key).slice(0, 120),
      pricingUrl: url,
      hubspotRecordId: t.hubspotRecordId ? String(t.hubspotRecordId) : null,
    });
  });
}

const apifyInputDefaults = parseJsonEnv('APIFY_ACTOR_INPUT_JSON', {});

// ── Derived hard gates
const liveFetchReady = hasApifyToken && hasHubspotToken && competitorTargets.length > 0;
let sandboxMode = sandboxRequested;
if (!sandboxRequested && !liveFetchReady) {
  sandboxMode = true;
  const missing = [
    !hasApifyToken && 'APIFY_API_TOKEN',
    !hasHubspotToken && 'HUBSPOT_ACCESS_TOKEN',
    competitorTargets.length === 0 && 'COMPETITOR_TARGETS_JSON',
  ].filter(Boolean).join(', ');
  warnings.push(`SANDBOX_MODE=false but live prerequisites are missing (${missing}). Forced back to sandbox fixtures.`);
}

const allowHubspotWrite = !sandboxMode && !dryRun && hubspotLoggingEnabled && hasHubspotToken;
const allowSlackSend = sendSlackAlerts && !dryRun && hasSlackWebhook;
const allowOpsAlert = sendOpsAlerts && !dryRun && hasAlertWebhook;

let writeBlockedReason = null;
if (!allowHubspotWrite) {
  writeBlockedReason = sandboxMode ? 'sandbox_mode'
    : dryRun ? 'dry_run'
    : !hubspotLoggingEnabled ? 'hubspot_logging_disabled'
    : 'missing_hubspot_token';
}

const modeLabel = sandboxMode ? 'SANDBOX' : (dryRun ? 'LIVE-DRY-RUN' : 'LIVE');
const stamp = runDate.toISOString().replace(/[-:]/g, '').replace(/\..+$/, '').replace('T', '-');
const execId = (typeof $execution !== 'undefined' && $execution && $execution.id) ? String($execution.id) : 'manual';

return [{
  json: {
    runId: `cpdt-${stamp}-${execId}`,
    runStartedAt: runDate.toISOString(),
    runDate: runDate.toISOString().slice(0, 10),
    isoWeek: isoWeek(runDate),
    modeLabel,
    envAccessible,

    // Safety flags as requested + effective gates
    sandboxRequested,
    sandboxMode,
    dryRun,
    hubspotLoggingEnabled,
    sendSlackAlerts,
    sendOpsAlerts,
    allowHubspotWrite,
    allowSlackSend,
    allowOpsAlert,
    writeBlockedReason,

    // Secret presence only (never values)
    secretsPresent: { hasHubspotToken, hasApifyToken, hasSlackWebhook, hasAlertWebhook },

    // Integration identifiers (non-secret placeholders by default)
    apifyActorId: readEnv('APIFY_ACTOR_ID') || 'mock-user~pricing-page-scraper',
    apifyRunTimeoutSecs: num('APIFY_RUN_TIMEOUT_SECS', 240, 30, 290),
    apifyInputDefaults: (apifyInputDefaults && typeof apifyInputDefaults === 'object' && !Array.isArray(apifyInputDefaults)) ? apifyInputDefaults : {},
    hubspotPortalId: readEnv('HUBSPOT_PORTAL_ID') || '99000001',
    hubspotObjectType: readEnv('HUBSPOT_COMPETITOR_OBJECT_TYPE') || 'p99000001_competitor_pricing',
    hubspotBatchSize: Math.floor(num('HUBSPOT_BATCH_SIZE', 50, 1, 100)),

    // Diff thresholds
    priceChangeThresholdPct: num('PRICE_CHANGE_THRESHOLD_PCT', 5, 0.1, 100),
    annualDiscountShiftThresholdPp: num('ANNUAL_DISCOUNT_SHIFT_THRESHOLD_PP', 5, 0.1, 100),
    suspectTierRemovalRatio: num('SUSPECT_TIER_REMOVAL_RATIO', 0.5, 0.05, 1),
    alertMinSeverity: oneOf('ALERT_MIN_SEVERITY', 'high', ['low', 'medium', 'high', 'critical']),

    competitorTargets,
    warnings,
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Load Sandbox Fixture
// Emits one item per competitor using SYNTHETIC data only. The embedded copy
