const cfg = $('Config & Safety Gate').first().json;
const targets = $('Build Live Targets').all();
const responses = $input.all();

if (responses.length !== targets.length) {
  throw new Error(`Apify response count (${responses.length}) does not match target count (${targets.length}); refusing to mis-pair snapshots.`);
}

const errText = (e) => {
  if (!e) return 'unknown error';
  if (typeof e === 'string') return e.slice(0, 300);
  return String(e.message || e.description || JSON.stringify(e)).slice(0, 300);
};

return responses.map((r, i) => {
  const t = targets[i].json;
  const body = r.json || {};
  let current = null;
  let fetchError = null;

  if (body.error) {
    fetchError = `Apify request failed: ${errText(body.error)}`;
  } else {
    let parsed = body.data;
    if (typeof parsed === 'string') {
      try { parsed = JSON.parse(parsed); } catch (e) { parsed = null; fetchError = 'Apify response was not valid JSON.'; }
    }
    const items = Array.isArray(parsed) ? parsed : (parsed ? [parsed] : []);
    const looksLikeSnapshot = (it) => it && typeof it === 'object' && (Array.isArray(it.tiers) || Array.isArray(it.plans) || (it.pricing && typeof it.pricing === 'object'));
    const match = items.find((it) => looksLikeSnapshot(it) && it.competitorKey === t.competitorKey)
      || items.find(looksLikeSnapshot)
      || null;
    if (!fetchError && !match) fetchError = 'Apify dataset contained no pricing snapshot item.';
    if (match) current = { ...match, capturedAt: match.capturedAt || cfg.runStartedAt };
  }

  const { apifyInput, ...rest } = t;
  return {
    json: {
      ...rest,
      current,
      fetchError,
      currentSnapshotKey: `${t.competitorKey}__${cfg.isoWeek}`,
      hubspotSearchBody: {
        filterGroups: [{
          filters: [
            { propertyName: 'competitor_key', operator: 'EQ', value: t.competitorKey },
            { propertyName: 'snapshot_key', operator: 'NEQ', value: `${t.competitorKey}__${cfg.isoWeek}` },
            { propertyName: 'snapshot_valid', operator: 'EQ', value: 'true' },
          ],
        }],
        sorts: [{ propertyName: 'snapshot_date', direction: 'DESCENDING' }],
        properties: ['snapshot_key', 'snapshot_date', 'snapshot_json', 'snapshot_fingerprint'],
        limit: 1,
      },
    },
    pairedItem: { item: i },
  };
});

// ─────────────────────────────────────────────────────────────────────────────
// Assemble Live Snapshot Pairs
// Joins each HubSpot search response (in order) with its Apify result to
// produce the { current, previous } pair the diff engine expects. A failed
// lookup is treated as an error, never as "first observation", so a HubSpot
// outage cannot silently reset history to a baseline.
// ─────────────────────────────────────────────────────────────────────────────
const base = $('Attach Apify Result').all();
const responses = $input.all();

if (responses.length !== base.length) {
  throw new Error(`HubSpot lookup count (${responses.length}) does not match competitor count (${base.length}); refusing to mis-pair snapshots.`);
}

return responses.map((r, i) => {
  const b = base[i].json;
  const body = r.json || {};
  let previous = null;
  let previousSnapshotKey = null;
  let previousFingerprint = null;
  let fetchError = b.fetchError || null;

  if (body.error) {
    const msg = typeof body.error === 'string' ? body.error : (body.error.message || 'request failed');
    fetchError = fetchError || `HubSpot previous-snapshot lookup failed: ${String(msg).slice(0, 300)}`;
  } else {
    const hit = Array.isArray(body.results) ? body.results[0] : null;
    const props = hit && hit.properties ? hit.properties : null;
    if (props && props.snapshot_json) {
      try {
        previous = JSON.parse(props.snapshot_json);
        previousSnapshotKey = props.snapshot_key || null;
        previousFingerprint = props.snapshot_fingerprint || null;
      } catch (e) {
        fetchError = fetchError || `Previous snapshot ${props.snapshot_key || '(unknown)'} has unparseable snapshot_json.`;
      }
    }
  }

  const { hubspotSearchBody, ...rest } = b;
  return {
    json: { ...rest, previous, previousSnapshotKey, previousFingerprint, fetchError },
    pairedItem: { item: i },
  };
});

// ─────────────────────────────────────────────────────────────────────────────
// Pricing Diff & Intelligence Engine  (Run Once for All Items)
// 1. Normalises current + previous pricing snapshots into a canonical shape.
// 2. Fingerprints them; identical structure → fast "no_change" path.
// 3. Computes structural diffs: pricing-model shifts, tier additions/removals/
//    renames, monthly + annual price moves, contact-sales transitions, billing
//    unit changes, seat limits, annual-discount shifts, free tier / trial
//    changes, feature gating moves (up/down tiers), feature limit changes.
// 4. Scores severity against env thresholds and flags suspect scrapes.
// 5. Emits HubSpot custom-object upsert inputs (one record per competitor/week).
// Pure JavaScript: no network, no require(), runs identically in the simulator.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
const THRESHOLD = Number(cfg.priceChangeThresholdPct);
const DISCOUNT_PP = Number(cfg.annualDiscountShiftThresholdPp);
const SUSPECT_RATIO = Number(cfg.suspectTierRemovalRatio);
const MAX_TEXT = 60000;

const SEVERITIES = ['none', 'low', 'medium', 'high', 'critical'];
const sevRank = (s) => Math.max(0, SEVERITIES.indexOf(s));
const maxSev = (a, b) => (sevRank(a) >= sevRank(b) ? a : b);
const ALERT_MIN_RANK = sevRank(cfg.alertMinSeverity);
const MODELS = ['per_seat', 'flat_rate', 'usage_based', 'tiered', 'hybrid', 'unknown'];

// ── Helpers ──────────────────────────────────────────────────────────────────
const round2 = (n) => Math.round(n * 100) / 100;
const slug = (v) => String(v ?? '').toLowerCase().normalize('NFKD')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 64);

const toPrice = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) && v >= 0 ? round2(v) : null;
  const s = String(v).trim();
  if (/^free$/i.test(s)) return 0;
  if (/contact|custom|quote|talk to/i.test(s)) return null;
  const m = s.replace(/,/g, '').match(/\d+(\.\d+)?/);
  if (!m) return null;
  const n = parseFloat(m[0]);
  return Number.isFinite(n) ? round2(n) : null;
};

const toSeats = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'string' && /unlimited|∞/i.test(v)) return 'unlimited';
  const n = parseInt(String(v).replace(/,/g, ''), 10);
  return Number.isFinite(n) && n >= 0 ? n : null;
};

const normModel = (v) => {
  const s = slug(v).replace(/-/g, '_');
  const alias = { seat: 'per_seat', per_user: 'per_seat', flat: 'flat_rate', usage: 'usage_based', metered: 'usage_based', consumption: 'usage_based' };
  const m = alias[s] || s;
  return MODELS.includes(m) ? m : 'unknown';
};

const normFeatures = (f) => {
  const out = {};
  if (Array.isArray(f)) {
    for (const k of f) { const key = slug(k).replace(/-/g, '_'); if (key) out[key] = true; }
  } else if (f && typeof f === 'object') {
    for (const [k, v] of Object.entries(f)) {
      const key = slug(k).replace(/-/g, '_');
      if (!key) continue;
      if (v === false || v === null || v === undefined || ['no', 'none', '-', '—', 'false'].includes(String(v).trim().toLowerCase())) out[key] = false;
      else if (v === true || ['yes', 'included', 'true', '✓'].includes(String(v).trim().toLowerCase())) out[key] = true;
      else out[key] = typeof v === 'number' ? v : String(v).trim();
    }
  }
  return Object.fromEntries(Object.keys(out).sort().map((k) => [k, out[k]]));
};
const featureOn = (v) => v !== false && v !== null && v !== undefined;

const normTier = (t, idx) => {
  if (!t || typeof t !== 'object') return null;
  const name = String(t.name ?? t.title ?? t.id ?? `Tier ${idx + 1}`).trim().slice(0, 80);
  const monthlyRaw = t.monthlyPrice ?? t.priceMonthly ?? t.monthly;
  const annualRaw = t.annualPricePerMonth ?? t.annualPrice ?? t.priceAnnualPerMonth ?? t.annual;
  const monthlyPrice = toPrice(monthlyRaw);
  const annualPricePerMonth = toPrice(annualRaw);
  const label = `${t.priceLabel ?? ''} ${typeof monthlyRaw === 'string' ? monthlyRaw : ''}`;
  const isContactSales = Boolean(t.isContactSales) || (monthlyPrice === null && annualPricePerMonth === null && /contact|custom|quote|talk to/i.test(label));
  return {
    id: slug(t.id ?? t.key ?? name) || `tier-${idx + 1}`,
    name,
    position: idx,
    monthlyPrice: isContactSales ? null : monthlyPrice,
    annualPricePerMonth: isContactSales ? null : annualPricePerMonth,
    billingUnit: slug(t.billingUnit || (isContactSales ? 'custom' : 'per_month')).replace(/-/g, '_'),
    seatLimit: toSeats(t.seatLimit),
    includedSeats: toSeats(t.includedSeats),
    isContactSales,
    features: normFeatures(t.features),
  };
};

const normSnapshot = (raw) => {
  if (!raw || typeof raw !== 'object') return null;
  const src = raw.pricing && typeof raw.pricing === 'object' && !Array.isArray(raw.pricing) ? { ...raw, ...raw.pricing } : raw;
  const list = Array.isArray(src.tiers) ? src.tiers : (Array.isArray(src.plans) ? src.plans : []);
  const tiers = [];
  const ids = new Set();
  list.forEach((t, i) => {
    const n = normTier(t, i);
    if (!n) return;
    let id = n.id; let k = 2;
    while (ids.has(id)) id = `${n.id}-${k++}`;
    ids.add(id);
    tiers.push({ ...n, id, position: tiers.length });
  });
  const trial = src.freeTrialDays === null || src.freeTrialDays === undefined ? null : parseInt(src.freeTrialDays, 10);
  return {
    capturedAt: src.capturedAt ? new Date(src.capturedAt).toISOString() : null,
    currency: String(src.currency || 'USD').toUpperCase().slice(0, 3),
    pricingModel: normModel(src.pricingModel),
    freeTrialDays: Number.isFinite(trial) ? trial : null,
    tiers,
  };
};

const stable = (v) => {
  if (Array.isArray(v)) return `[${v.map(stable).join(',')}]`;
  if (v && typeof v === 'object') return `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${stable(v[k])}`).join(',')}}`;
  return JSON.stringify(v);
};
const fnv1a = (str, seed) => {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
};
const fingerprint = (snap) => {
  const { capturedAt, ...structure } = snap;
  const s = stable(structure);
  return `fp-${fnv1a(s, 0x811c9dc5)}${fnv1a(s, 0x01000193)}`;
};

const isoWeek = (d) => {
  const date = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const day = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return `${date.getUTCFullYear()}-W${String(Math.ceil(((date - yearStart) / 86400000 + 1) / 7)).padStart(2, '0')}`;
};

const SYMBOLS = { USD: '$', EUR: '€', GBP: '£', CAD: 'CA$', AUD: 'A$', JPY: '¥', INR: '₹' };
const money = (v, cur) => (v === null || v === undefined ? 'n/a' : `${SYMBOLS[cur] || `${cur} `}${Number(v).toFixed(2)}`);
const pct = (a, b) => (a > 0 && b !== null ? round2(((b - a) / a) * 100) : null);
const signed = (n) => `${n > 0 ? '+' : ''}${n.toFixed(1)}%`;
const discountPct = (t) => (t.monthlyPrice > 0 && t.annualPricePerMonth !== null ? round2(((t.monthlyPrice - t.annualPricePerMonth) / t.monthlyPrice) * 100) : null);
const fmtSeats = (v) => (v === null ? 'not stated' : String(v));

const metrics = (snap) => {
  const paid = snap.tiers.map((t) => t.monthlyPrice).filter((p) => p !== null && p > 0);
  const listed = snap.tiers.map((t) => t.monthlyPrice).filter((p) => p !== null);
  const discounts = snap.tiers.map(discountPct).filter((d) => d !== null);
  return {
    tierCount: snap.tiers.length,
    lowestPaidMonthly: paid.length ? Math.min(...paid) : null,
    highestListedMonthly: listed.length ? Math.max(...listed) : null,
    hasFreeTier: snap.tiers.some((t) => t.monthlyPrice === 0),
    contactSalesTiers: snap.tiers.filter((t) => t.isContactSales).length,
    avgAnnualDiscountPct: discounts.length ? round2(discounts.reduce((a, b) => a + b, 0) / discounts.length) : null,
  };
};

const priceSeverity = (p, direction) => {
  const a = Math.abs(p);
  if (direction === 'increase' && a >= THRESHOLD * 2) return 'critical';
  if (a >= THRESHOLD) return 'high';
  return 'low';
};

// Rank tiers by entry price (contact-sales last) to reason about feature gating.
const tierRanks = (snap) => {
  const ordered = [...snap.tiers].sort((a, b) => {
    const pa = a.isContactSales ? Infinity : (a.monthlyPrice ?? Infinity);
    const pb = b.isContactSales ? Infinity : (b.monthlyPrice ?? Infinity);
    return pa - pb || a.position - b.position;
  });
  return new Map(ordered.map((t, i) => [t.id, i]));
};
const lowestTierWith = (snap, ranks, feature) => {
  let best = null;
  for (const t of snap.tiers) {
    if (!featureOn(t.features[feature])) continue;
    if (!best || ranks.get(t.id) < ranks.get(best.id)) best = t;
  }
  return best;
};

// ── Structural diff ─────────────────────────────────────────────────────────
const diffSnapshots = (prev, curr) => {
  const changes = [];
  const add = (c) => changes.push(c);
  const cur = curr.currency;
  const comparable = prev.currency === curr.currency;

  if (!comparable) {
    add({ type: 'currency_changed', severity: 'high', before: prev.currency, after: curr.currency,
      message: `Displayed currency changed ${prev.currency} → ${curr.currency}; price percentages suppressed.` });
  }
  if (prev.pricingModel !== curr.pricingModel) {
    add({ type: 'pricing_model_shift', severity: 'critical', before: prev.pricingModel, after: curr.pricingModel,
      message: `Pricing model shifted ${prev.pricingModel} → ${curr.pricingModel}.` });
  }
  if (prev.freeTrialDays !== curr.freeTrialDays) {
    const msg = curr.freeTrialDays === null ? `Free trial removed (was ${prev.freeTrialDays} days).`
      : prev.freeTrialDays === null ? `Free trial introduced (${curr.freeTrialDays} days).`
      : `Free trial changed ${prev.freeTrialDays} → ${curr.freeTrialDays} days.`;
    add({ type: 'free_trial_changed', severity: 'medium', before: prev.freeTrialDays, after: curr.freeTrialDays, message: msg });
  }

  // Tier matching: by id, then rename detection (same slot + identical prices).
  const prevById = new Map(prev.tiers.map((t) => [t.id, t]));
  const currById = new Map(curr.tiers.map((t) => [t.id, t]));
  const pairs = [];
  const prevToCurr = new Map();
  for (const p of prev.tiers) if (currById.has(p.id)) { pairs.push([p, currById.get(p.id)]); prevToCurr.set(p.id, p.id); }
  let removed = prev.tiers.filter((t) => !currById.has(t.id));
  let added = curr.tiers.filter((t) => !prevById.has(t.id));
  for (const r of [...removed]) {
    const m = added.find((a) => a.position === r.position && a.monthlyPrice === r.monthlyPrice
      && a.annualPricePerMonth === r.annualPricePerMonth && a.isContactSales === r.isContactSales);
    if (m) {
      pairs.push([r, m]);
      prevToCurr.set(r.id, m.id);
      removed = removed.filter((x) => x !== r);
      added = added.filter((x) => x !== m);
    }
  }
  for (const r of removed) {
    add({ type: 'tier_removed', severity: 'high', tierId: r.id, tierName: r.name, before: r.name, after: null,
      message: `Tier "${r.name}" removed${r.monthlyPrice !== null ? ` (was ${money(r.monthlyPrice, prev.currency)}/mo)` : ''}.` });
  }
  for (const a of added) {
    add({ type: 'tier_added', severity: 'medium', tierId: a.id, tierName: a.name, before: null, after: a.name,
      message: `Tier "${a.name}" added${a.isContactSales ? ' (contact sales)' : a.monthlyPrice !== null ? ` at ${money(a.monthlyPrice, cur)}/mo` : ''}.` });
  }

  let maxPriceChangePct = null;
  const trackPct = (p) => { if (p !== null && (maxPriceChangePct === null || Math.abs(p) > Math.abs(maxPriceChangePct))) maxPriceChangePct = p; };

  for (const [p, c] of pairs) {
    const tier = { tierId: c.id, tierName: c.name };
    if (p.name !== c.name) {
      add({ ...tier, type: 'tier_renamed', severity: 'low', before: p.name, after: c.name, message: `Tier "${p.name}" renamed to "${c.name}".` });
    }
    if (!p.isContactSales && c.isContactSales) {
      add({ ...tier, type: 'moved_to_contact_sales', severity: 'critical', before: p.monthlyPrice, after: null,
        message: `"${c.name}" pricing hidden behind contact sales (was ${money(p.monthlyPrice, prev.currency)}/mo).` });
      continue;
    }
    if (p.isContactSales && !c.isContactSales) {
      add({ ...tier, type: 'price_published', severity: 'medium', before: null, after: c.monthlyPrice,
        message: `"${c.name}" now publishes pricing at ${money(c.monthlyPrice, cur)}/mo (was contact sales).` });
    }
    if (p.billingUnit !== c.billingUnit) {
      add({ ...tier, type: 'billing_unit_changed', severity: 'high', before: p.billingUnit, after: c.billingUnit,
        message: `"${c.name}" billing unit changed ${p.billingUnit} → ${c.billingUnit}.` });
    }
    for (const [field, label] of [['monthlyPrice', 'monthly'], ['annualPricePerMonth', 'annual (per mo)']]) {
      const a = p[field]; const b = c[field];
      if (a === b || p.isContactSales || c.isContactSales) continue;
      if (a !== null && b === null) {
        add({ ...tier, type: 'price_unpublished', severity: 'medium', field, before: a, after: null, message: `"${c.name}" ${label} price no longer listed.` });
        continue;
      }
      if (a === null && b !== null) {
        add({ ...tier, type: 'price_published', severity: 'low', field, before: null, after: b, message: `"${c.name}" ${label} price now listed at ${money(b, cur)}.` });
        continue;
      }
      if (!comparable) continue;
      if (a === 0 && b > 0) {
        add({ ...tier, type: 'price_increase', severity: 'high', field, before: a, after: b, pctChange: null,
          message: `"${c.name}" ${label} went from free to ${money(b, cur)}.` });
        continue;
      }
      const change = pct(a, b);
      if (change === null) continue;
      const direction = change > 0 ? 'increase' : 'decrease';
      trackPct(change);
      add({ ...tier, type: `price_${direction}`, severity: priceSeverity(change, direction), field, before: a, after: b, pctChange: change,
        material: Math.abs(change) >= THRESHOLD,
        message: `"${c.name}" ${label} ${money(a, cur)} → ${money(b, cur)} (${signed(change)}).` });
    }
    const da = discountPct(p); const db = discountPct(c);
    if (da !== null && db !== null && Math.abs(db - da) >= DISCOUNT_PP) {
      add({ ...tier, type: 'annual_discount_shift', severity: 'medium', before: da, after: db, pctChange: round2(db - da),
        message: `"${c.name}" annual discount ${da.toFixed(1)}% → ${db.toFixed(1)}% (${db - da > 0 ? '+' : ''}${(db - da).toFixed(1)} pp).` });
    }
    for (const [field, label] of [['seatLimit', 'seat limit'], ['includedSeats', 'included seats']]) {
      if (p[field] !== c[field]) {
        add({ ...tier, type: field === 'seatLimit' ? 'seat_limit_changed' : 'included_seats_changed', severity: 'medium', field, before: p[field], after: c[field],
          message: `"${c.name}" ${label} ${fmtSeats(p[field])} → ${fmtSeats(c[field])}.` });
      }
    }
    for (const fk of Object.keys(c.features)) {
      const fa = p.features[fk]; const fb = c.features[fk];
      if (featureOn(fa) && featureOn(fb) && fa !== true && fb !== true && String(fa) !== String(fb)) {
        add({ ...tier, type: 'feature_limit_changed', severity: 'low', feature: fk, before: fa, after: fb,
          message: `"${c.name}" ${fk} limit ${fa} → ${fb}.` });
      }
    }
  }

  // Feature gating across the whole page.
  const prevRanks = tierRanks(prev); const currRanks = tierRanks(curr);
  const allFeatures = new Set();
  for (const t of [...prev.tiers, ...curr.tiers]) Object.keys(t.features).forEach((k) => allFeatures.add(k));
  for (const fk of [...allFeatures].sort()) {
    const pLow = lowestTierWith(prev, prevRanks, fk);
    const cLow = lowestTierWith(curr, currRanks, fk);
    if (!pLow && cLow) {
      add({ type: 'feature_added', severity: 'low', feature: fk, tierId: cLow.id, tierName: cLow.name, before: null, after: cLow.name,
        message: `Feature "${fk}" now offered (from "${cLow.name}").` });
    } else if (pLow && !cLow) {
      add({ type: 'feature_removed', severity: 'medium', feature: fk, tierId: pLow.id, tierName: pLow.name, before: pLow.name, after: null,
        message: `Feature "${fk}" no longer offered on any tier (was from "${pLow.name}").` });
    } else if (pLow && cLow) {
      const mapped = prevToCurr.get(pLow.id);
      if (mapped === cLow.id) continue;
      let direction;
      if (mapped && currRanks.has(mapped)) direction = currRanks.get(cLow.id) > currRanks.get(mapped) ? 'up' : 'down';
      else {
        const pe = pLow.isContactSales ? Infinity : (pLow.monthlyPrice ?? Infinity);
        const ce = cLow.isContactSales ? Infinity : (cLow.monthlyPrice ?? Infinity);
        if (pe === ce) continue;
        direction = ce > pe ? 'up' : 'down';
      }
      add({ type: direction === 'up' ? 'feature_gated_up' : 'feature_gated_down', severity: 'medium', feature: fk,
        tierId: cLow.id, tierName: cLow.name, before: pLow.name, after: cLow.name,
        message: direction === 'up'
          ? `Feature "${fk}" moved up-market: now requires "${cLow.name}" (was "${pLow.name}").`
          : `Feature "${fk}" moved down-market: now available from "${cLow.name}" (was "${pLow.name}").` });
    }
  }

  // Snapshot-level free tier signal.
  const pm = metrics(prev); const cm = metrics(curr);
  if (pm.hasFreeTier && !cm.hasFreeTier) add({ type: 'free_tier_removed', severity: 'high', before: true, after: false, message: 'Free tier removed.' });
  if (!pm.hasFreeTier && cm.hasFreeTier) add({ type: 'free_tier_added', severity: 'high', before: false, after: true, message: 'Free tier introduced.' });

  const removalRatio = prev.tiers.length ? removed.length / prev.tiers.length : 0;
  return { changes, maxPriceChangePct, removedCount: removed.length, addedCount: added.length, removalRatio };
};

const severityOrder = (a, b) => sevRank(b.severity) - sevRank(a.severity);
const clip = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);

// ── Per-competitor analysis ─────────────────────────────────────────────────
const analyse = (j, key) => {
  const name = String(j.competitorName || key);
  const snapshotKey = `${key}__${cfg.isoWeek}`;
  const base = {
    competitorKey: key, competitorName: name, hubspotRecordId: j.hubspotRecordId ?? null,
    sourceUrl: j.sourceUrl ?? null, source: j.source ?? 'unknown', snapshotKey,
    previousSnapshotKey: j.previousSnapshotKey ?? null, reviewReasons: [], changes: [],
  };

  if (j.fetchError || !j.current) {
    return { ...base, status: 'fetch_failed', severity: 'none', alertWorthy: false, requiresReview: true,
      reviewReasons: [j.fetchError || 'No current snapshot was returned.'], headline: `${name}: snapshot unavailable — ${j.fetchError || 'no data'}`,
      record: null };
  }

  const curr = normSnapshot(j.current);
  const prev = j.previous ? normSnapshot(j.previous) : null;
  if (!curr.capturedAt) curr.capturedAt = cfg.runStartedAt;
  const currFp = fingerprint(curr);
  const prevFp = prev ? fingerprint(prev) : null;
  const previousSnapshotKey = base.previousSnapshotKey || (prev && prev.capturedAt ? `${key}__${isoWeek(new Date(prev.capturedAt))}` : null);

  let status; let changes = []; let severity = 'none'; let maxPriceChangePct = null;
  let removedCount = 0; let addedCount = 0; let snapshotValid = true;
  const reviewReasons = [];

  if (curr.tiers.length === 0) {
    status = 'review_required';
    snapshotValid = false;
    reviewReasons.push('Scrape returned zero pricing tiers (likely page layout change or blocked crawl). Diff skipped; previous valid snapshot retained as baseline.');
  } else if (!prev) {
    status = 'baseline';
  } else if (prevFp === currFp) {
    status = 'no_change';
  } else {
    const d = diffSnapshots(prev, curr);
    changes = d.changes.sort(severityOrder);
    maxPriceChangePct = d.maxPriceChangePct;
    removedCount = d.removedCount; addedCount = d.addedCount;
    severity = changes.reduce((s, c) => maxSev(s, c.severity), 'none');
    status = changes.length ? 'changed' : 'no_change';
    if (d.removalRatio > SUSPECT_RATIO) {
      status = 'review_required';
      snapshotValid = false;
      reviewReasons.push(`${Math.round(d.removalRatio * 100)}% of previous tiers disappeared in one run (threshold ${Math.round(SUSPECT_RATIO * 100)}%). Confirm on the live page, then set snapshot_valid=true in HubSpot.`);
    }
  }

  const requiresReview = reviewReasons.length > 0;
  const alertWorthy = requiresReview || (status === 'changed' && sevRank(severity) >= ALERT_MIN_RANK);
  const count = (pred) => changes.filter(pred).length;
  const counts = {
    total: changes.length,
    material: count((c) => sevRank(c.severity) >= sevRank('high')),
    priceIncreases: count((c) => c.type === 'price_increase'),
    priceDecreases: count((c) => c.type === 'price_decrease'),
    tiersAdded: addedCount,
    tiersRemoved: removedCount,
    featureGatingMoves: count((c) => c.type === 'feature_gated_up' || c.type === 'feature_gated_down'),
    pricingModelShift: changes.some((c) => c.type === 'pricing_model_shift'),
  };

  let headline;
  if (status === 'baseline') headline = `${name}: baseline captured (${curr.tiers.length} tiers, ${curr.pricingModel}).`;
  else if (status === 'no_change') headline = `${name}: no structural pricing change.`;
  else if (curr.tiers.length === 0) headline = `${name}: scrape returned no tiers — needs review.`;
  else {
    const bits = [];
    if (counts.pricingModelShift) bits.push('pricing model shift');
    if (counts.priceIncreases) bits.push(`${counts.priceIncreases} price increase${counts.priceIncreases > 1 ? 's' : ''}`);
    if (counts.priceDecreases) bits.push(`${counts.priceDecreases} price decrease${counts.priceDecreases > 1 ? 's' : ''}`);
    if (addedCount) bits.push(`${addedCount} tier${addedCount > 1 ? 's' : ''} added`);
    if (removedCount) bits.push(`${removedCount} tier${removedCount > 1 ? 's' : ''} removed`);
    if (counts.featureGatingMoves) bits.push(`${counts.featureGatingMoves} feature gating move${counts.featureGatingMoves > 1 ? 's' : ''}`);
    const other = counts.total - counts.priceIncreases - counts.priceDecreases - addedCount - removedCount - counts.featureGatingMoves - (counts.pricingModelShift ? 1 : 0);
    if (other > 0) bits.push(`${other} other change${other > 1 ? 's' : ''}`);
    headline = `${name}: ${bits.join(', ')}${maxPriceChangePct !== null ? ` (max ${signed(maxPriceChangePct)})` : ''}.`;
  }

  const currMetrics = metrics(curr);
  const diffSummary = clip(changes.length ? changes.map((c) => `[${c.severity.toUpperCase()}] ${c.message}`).join('\n') : headline, 5000);
  let diffJson = JSON.stringify(changes);
  let diffTruncated = false;
  if (diffJson.length > MAX_TEXT) { diffJson = JSON.stringify(changes.slice(0, 50)); diffTruncated = true; }
  const snapshotJson = JSON.stringify(curr);
  if (snapshotJson.length > MAX_TEXT) {
    snapshotValid = false;
    reviewReasons.push(`Normalised snapshot exceeds ${MAX_TEXT} characters and cannot be stored as a future baseline.`);
  }

  const properties = {
    snapshot_key: snapshotKey,
    competitor_key: key,
    competitor_name: name,
    competitor_record_id: j.hubspotRecordId ?? undefined,
    snapshot_date: cfg.runDate,
    snapshot_status: status,
    snapshot_valid: String(snapshotValid),
    source_url: j.sourceUrl ?? undefined,
    data_source: j.source ?? 'unknown',
    pricing_model: curr.pricingModel,
    currency: curr.currency,
    tier_count: currMetrics.tierCount,
    lowest_paid_monthly_price: currMetrics.lowestPaidMonthly ?? undefined,
    highest_listed_monthly_price: currMetrics.highestListedMonthly ?? undefined,
    change_severity: severity,
    change_count: counts.total,
    material_change_count: counts.material,
    max_price_change_pct: maxPriceChangePct ?? undefined,
    price_increase_count: counts.priceIncreases,
    price_decrease_count: counts.priceDecreases,
    tiers_added_count: addedCount,
    tiers_removed_count: removedCount,
    pricing_model_shift: String(counts.pricingModelShift),
    requires_review: String(reviewReasons.length > 0),
    review_reasons: reviewReasons.length ? clip(reviewReasons.join('\n'), 5000) : undefined,
    diff_summary: diffSummary,
    diff_json: diffJson,
    diff_truncated: String(diffTruncated),
    snapshot_json: snapshotJson.length > MAX_TEXT ? undefined : snapshotJson,
    snapshot_fingerprint: currFp,
    previous_snapshot_key: previousSnapshotKey ?? undefined,
    run_id: cfg.runId,
  };
  for (const k of Object.keys(properties)) if (properties[k] === undefined || properties[k] === null) delete properties[k];
  for (const k of Object.keys(properties)) if (typeof properties[k] === 'number') properties[k] = String(properties[k]);

  return {
    ...base,
    status,
    severity,
    alertWorthy: alertWorthy || reviewReasons.length > 0,
    requiresReview: reviewReasons.length > 0,
    reviewReasons,
    headline,
    changes,
    counts,
    maxPriceChangePct,
    previousSnapshotKey,
    snapshotValid,
    fingerprint: { previous: prevFp, current: currFp },
    metrics: { previous: prev ? metrics(prev) : null, current: currMetrics },
    currency: curr.currency,
    pricingModel: { previous: prev ? prev.pricingModel : null, current: curr.pricingModel },
    record: { idProperty: 'snapshot_key', id: snapshotKey, properties },
  };
};

// ── Main ────────────────────────────────────────────────────────────────────
const results = [];
const errors = [];
$input.all().forEach((item, idx) => {
  const j = item.json || {};
  const key = slug(j.competitorKey || j.competitorName) || `competitor-${idx + 1}`;
  try {
    results.push(analyse(j, key));
  } catch (e) {
    errors.push({ competitorKey: key, stage: 'diff_engine', message: String(e && e.message ? e.message : e).slice(0, 300) });
    results.push({ competitorKey: key, competitorName: String(j.competitorName || key), status: 'engine_error', severity: 'none',
      alertWorthy: true, requiresReview: true, reviewReasons: [`Diff engine error: ${String(e && e.message ? e.message : e).slice(0, 200)}`],
      headline: `${j.competitorName || key}: diff engine error.`, changes: [], record: null });
  }
});

const hubspotRecords = results.filter((r) => r.record).map((r) => r.record);
const bySeverity = Object.fromEntries(SEVERITIES.map((s) => [s, results.filter((r) => r.severity === s).length]));
const byStatus = {};
for (const r of results) byStatus[r.status] = (byStatus[r.status] || 0) + 1;

return [{
  json: {
    runId: cfg.runId,
    modeLabel: cfg.modeLabel,
    isoWeek: cfg.isoWeek,
    thresholds: { priceChangeThresholdPct: THRESHOLD, annualDiscountShiftThresholdPp: DISCOUNT_PP, suspectTierRemovalRatio: SUSPECT_RATIO, alertMinSeverity: cfg.alertMinSeverity },
    results: results.map(({ record, ...rest }) => rest),
    hubspotRecords,
    stats: {
      competitorsProcessed: results.length,
      byStatus,
      bySeverity,
      alertWorthy: results.filter((r) => r.alertWorthy).length,
      totalChanges: results.reduce((a, r) => a + (r.changes ? r.changes.length : 0), 0),
      recordsPrepared: hubspotRecords.length,
    },
    errors,
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Build HubSpot Batches
// Chunks upsert inputs into HubSpot-sized batches (max 100, default 50).
// Always emits at least one item so the write gate IF node always executes.
// allowWrite is true ONLY when the Config & Safety Gate opened the CRM gate.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
const engine = $input.first().json;
const records = Array.isArray(engine.hubspotRecords) ? engine.hubspotRecords : [];
const size = Math.min(100, Math.max(1, Number(cfg.hubspotBatchSize) || 50));

if (records.length === 0) {
  return [{ json: { empty: true, allowWrite: false, batchIndex: -1, batchCount: 0, recordKeys: [], request: { inputs: [] } } }];
}

const batches = [];
for (let i = 0; i < records.length; i += size) batches.push(records.slice(i, i + size));

return batches.map((inputs, i) => ({
  json: {
    empty: false,
    allowWrite: cfg.allowHubspotWrite === true,
    batchIndex: i,
    batchCount: batches.length,
    objectType: cfg.hubspotObjectType,
    recordKeys: inputs.map((r) => r.id),
    request: { inputs },
  },
  pairedItem: { item: 0 },
}));

// ─────────────────────────────────────────────────────────────────────────────
// Collect HubSpot Write Results
// Correlates each batch upsert response (in order) with its batch and reports
// written vs failed record keys. Never throws on partial failure: failures are
// surfaced to the Execution Summary and the ops alert gate.
// ─────────────────────────────────────────────────────────────────────────────
const batches = $('Build HubSpot Batches').all();
const responses = $input.all();
const failures = [];
let recordsWritten = 0;
let recordsAttempted = 0;

responses.forEach((r, i) => {
  const b = batches[i] ? batches[i].json : { recordKeys: [], batchIndex: i };
  const body = r.json || {};
  recordsAttempted += b.recordKeys.length;
  if (body.error) {
    const msg = typeof body.error === 'string' ? body.error : (body.error.message || 'request failed');
    failures.push({ batchIndex: b.batchIndex, recordKeys: b.recordKeys, message: String(msg).slice(0, 300) });
    return;
  }
  const ok = Array.isArray(body.results) ? body.results.length : 0;
  recordsWritten += ok;
  if (Array.isArray(body.errors) && body.errors.length) {
    body.errors.forEach((e) => failures.push({ batchIndex: b.batchIndex, recordKeys: (e.context && e.context.ids) || [], message: String(e.message || e.category || 'record error').slice(0, 300) }));
  } else if (ok < b.recordKeys.length) {
    failures.push({ batchIndex: b.batchIndex, recordKeys: b.recordKeys, message: `HubSpot returned ${ok} of ${b.recordKeys.length} records.` });
  }
});

return [{
  json: {
    writeMode: 'live',
    batchesAttempted: responses.length,
    recordsAttempted,
    recordsWritten,
    failures,
    ok: failures.length === 0,
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Dry-Run Write Preview
// Reached whenever the CRM write gate is closed. Shows exactly what WOULD be
// written to HubSpot (endpoint, record keys, one sample record) — no network.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
const batches = $input.all().map((i) => i.json).filter((b) => !b.empty);
const inputs = batches.flatMap((b) => b.request.inputs);
const sample = inputs[0]
  ? {
    idProperty: inputs[0].idProperty,
    id: inputs[0].id,
    properties: Object.fromEntries(Object.entries(inputs[0].properties)
      .map(([k, v]) => [k, typeof v === 'string' && v.length > 240 ? `${v.slice(0, 240)}… (${v.length} chars)` : v])),
  }
  : null;

return [{
  json: {
    writeMode: 'preview',
    blockedReason: inputs.length ? cfg.writeBlockedReason : 'nothing_to_write',
    endpoint: `POST https://api.hubapi.com/crm/v3/objects/${cfg.hubspotObjectType}/batch/upsert`,
    portalId: cfg.hubspotPortalId,
    wouldWriteBatches: batches.length,
    wouldWriteRecords: inputs.length,
    recordKeys: inputs.map((r) => r.id),
    sampleRecord: sample,
    recordsWritten: 0,
    failures: [],
    ok: true,
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// RevOps Slack Block Kit Alert Builder
// Formats alert-worthy competitor changes into a Block Kit payload (≤ 50
// blocks, section text ≤ 3000 chars). The payload is always built so it can be
// previewed in dry runs; it is only SENT when allowSlackSend is true.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
const engine = $('Pricing Diff & Intelligence Engine').first().json;

let write = null;
try { write = $('Collect HubSpot Write Results').first().json; } catch (e) { /* not executed */ }
if (!write) { try { write = $('Dry-Run Write Preview').first().json; } catch (e) { /* not executed */ } }

const SEV_ORDER = ['none', 'low', 'medium', 'high', 'critical'];
const SEV_ICON = { critical: ':red_circle:', high: ':large_orange_circle:', medium: ':large_yellow_circle:', low: ':white_circle:', none: ':white_circle:' };
const TYPE_ICON = {
  price_increase: ':arrow_up:', price_decrease: ':arrow_down:', pricing_model_shift: ':arrows_counterclockwise:',
  tier_added: ':heavy_plus_sign:', tier_removed: ':heavy_minus_sign:', moved_to_contact_sales: ':lock:',
  feature_gated_up: ':arrow_heading_up:', feature_gated_down: ':arrow_heading_down:', free_tier_removed: ':no_entry:',
  free_tier_added: ':gift:', free_trial_changed: ':hourglass_flowing_sand:', tier_renamed: ':label:', billing_unit_changed: ':receipt:', annual_discount_shift: ':calendar:', seat_limit_changed: ':busts_in_silhouette:',
};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clip = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);

const alerts = engine.results
  .filter((r) => r.alertWorthy)
  .sort((a, b) => SEV_ORDER.indexOf(b.severity) - SEV_ORDER.indexOf(a.severity) || a.competitorName.localeCompare(b.competitorName));

const modeBadge = cfg.modeLabel === 'LIVE' ? ':satellite_antenna: LIVE' : cfg.modeLabel === 'SANDBOX' ? ':test_tube: SANDBOX (synthetic data)' : ':eyes: LIVE DRY RUN';
const s = engine.stats;
const writeLine = !write ? 'HubSpot: not attempted'
  : write.writeMode === 'live' ? `HubSpot: ${write.recordsWritten} record(s) upserted${write.failures.length ? `, ${write.failures.length} failure(s)` : ''}`
  : `HubSpot: preview only (${write.wouldWriteRecords} record(s), ${write.blockedReason})`;

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: clip(`Competitor pricing changes · ${engine.isoWeek}`, 150), emoji: true } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: clip(`${modeBadge}  ·  Run \`${esc(engine.runId)}\`  ·  ${s.competitorsProcessed} tracked  ·  ${alerts.length} need attention  ·  threshold ±${engine.thresholds.priceChangeThresholdPct}%`, 3000) }] },
  { type: 'divider' },
];

const MAX_COMPETITORS = 10;
for (const r of alerts.slice(0, MAX_COMPETITORS)) {
  const link = r.sourceUrl ? `  ·  <${r.sourceUrl}|pricing page>` : '';
  const sev = r.requiresReview && r.severity === 'none' ? ':warning: REVIEW' : `${SEV_ICON[r.severity]} ${r.severity.toUpperCase()}`;
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: clip(`*${esc(r.competitorName)}*  ·  ${sev}${link}\n${esc(r.headline)}`, 3000) } });

  const top = (r.changes || []).slice(0, 6);
  if (top.length) {
    const lines = top.map((c) => `${TYPE_ICON[c.type] || ':small_blue_diamond:'} ${esc(c.message)}`);
    if (r.changes.length > top.length) lines.push(`_…and ${r.changes.length - top.length} more (see HubSpot record \`${esc(r.snapshotKey)}\`)_`);
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: clip(lines.join('\n'), 3000) } });
  }
  if (r.metrics && r.metrics.current && r.status !== 'fetch_failed') {
    const m = r.metrics.current; const p = r.metrics.previous;
    const fields = [
      { type: 'mrkdwn', text: `*Model*\n${esc(r.pricingModel.previous && r.pricingModel.previous !== r.pricingModel.current ? `${r.pricingModel.previous} → ${r.pricingModel.current}` : r.pricingModel.current)}` },
      { type: 'mrkdwn', text: `*Tiers*\n${p ? `${p.tierCount} → ${m.tierCount}` : m.tierCount}` },
      { type: 'mrkdwn', text: `*Entry paid price*\n${m.lowestPaidMonthly === null ? 'n/a' : `${r.currency} ${m.lowestPaidMonthly.toFixed(2)}`}/mo` },
      { type: 'mrkdwn', text: `*Max price move*\n${r.maxPriceChangePct === null || r.maxPriceChangePct === undefined ? '—' : `${r.maxPriceChangePct > 0 ? '+' : ''}${r.maxPriceChangePct.toFixed(1)}%`}` },
    ];
    blocks.push({ type: 'section', fields });
  }
  if (r.requiresReview) {
    blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: clip(`:warning: *Needs human review:* ${esc(r.reviewReasons.join(' '))}`, 3000) }] });
  }
  blocks.push({ type: 'divider' });
}
if (alerts.length > MAX_COMPETITORS) {
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `_${alerts.length - MAX_COMPETITORS} more competitor(s) omitted — see the n8n execution summary._` }] });
}
const quiet = engine.results.filter((r) => !r.alertWorthy).map((r) => `${esc(r.competitorName)} (${r.status.replace('_', ' ')})`);
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: clip(`${quiet.length ? `No action needed: ${quiet.join(', ')}  ·  ` : ''}${writeLine}`, 3000) }] });

const safeBlocks = blocks.slice(0, 50);
const fallback = clip(`[${cfg.modeLabel}] Competitor pricing: ${alerts.length} competitor(s) need attention in ${engine.isoWeek}. ${alerts.map((a) => `${a.competitorName} (${a.requiresReview && a.severity === 'none' ? 'needs review' : a.severity})`).join(', ')}`, 3000);

let skipReason = null;
if (alerts.length === 0) skipReason = 'no_alert_worthy_changes';
else if (!cfg.sendSlackAlerts) skipReason = 'send_slack_alerts_disabled';
else if (cfg.dryRun) skipReason = 'dry_run';
else if (!cfg.secretsPresent.hasSlackWebhook) skipReason = 'missing_slack_webhook';

return [{
  json: {
    allowSend: cfg.allowSlackSend === true && alerts.length > 0,
    skipReason: cfg.allowSlackSend === true && alerts.length > 0 ? null : skipReason,
    alertCount: alerts.length,
    blockCount: safeBlocks.length,
    payload: { text: fallback, blocks: safeBlocks, unfurl_links: false, unfurl_media: false },
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Slack Alert Skipped
// Records why no Slack message was sent (gate closed or nothing alert-worthy).
// ─────────────────────────────────────────────────────────────────────────────
const b = $input.first().json;
return [{
  json: {
    slackStatus: 'skipped',
    skipReason: b.skipReason || 'gate_closed',
    alertCount: b.alertCount,
    blockCount: b.blockCount,
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Execution Summary & Audit
// Produces a single, secret-free audit record of the run: effective safety
// gates, per-competitor outcomes + fingerprints, CRM write outcome, Slack
// outcome, warnings, and a deterministic checksum. Decides whether the ops
// failure alert should fire (only if SEND_OPS_ALERTS gate is open).
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
const engine = $('Pricing Diff & Intelligence Engine').first().json;
const slackBuild = $('RevOps Slack Block Kit Builder').first().json;

let write = null;
try { write = $('Collect HubSpot Write Results').first().json; } catch (e) { /* not executed */ }
if (!write) { try { write = $('Dry-Run Write Preview').first().json; } catch (e) { /* not executed */ } }

const last = $input.first().json || {};
let slack;
if (last.slackStatus === 'skipped') slack = { status: 'skipped', reason: last.skipReason };
else if (last.error) slack = { status: 'failed', reason: String(typeof last.error === 'string' ? last.error : (last.error.message || 'request failed')).slice(0, 300) };
else slack = { status: String(last.data ?? '').trim() === 'ok' ? 'sent' : 'sent_unconfirmed', blocks: slackBuild.blockCount, alerts: slackBuild.alertCount };

const warnings = [...(cfg.warnings || [])];
const errors = [...(engine.errors || [])];
for (const r of engine.results) {
  if (r.status === 'fetch_failed') errors.push({ competitorKey: r.competitorKey, stage: 'fetch', message: r.reviewReasons.join(' ') });
  if (r.status === 'review_required') warnings.push(`${r.competitorName}: ${r.reviewReasons.join(' ')}`);
}
if (write && write.failures && write.failures.length) {
  write.failures.forEach((f) => errors.push({ stage: 'hubspot_write', batchIndex: f.batchIndex, recordKeys: f.recordKeys, message: f.message }));
}
if (slack.status === 'failed') errors.push({ stage: 'slack', message: slack.reason });

const status = errors.length ? 'completed_with_errors' : warnings.length ? 'completed_with_warnings' : 'success';
const finishedAt = new Date();
const startedAt = new Date(cfg.runStartedAt);

const competitors = engine.results.map((r) => ({
  competitorKey: r.competitorKey,
  competitorName: r.competitorName,
  status: r.status,
  severity: r.severity,
  alertWorthy: r.alertWorthy,
  changeCount: (r.changes || []).length,
  maxPriceChangePct: r.maxPriceChangePct ?? null,
  snapshotKey: r.snapshotKey ?? null,
  previousSnapshotKey: r.previousSnapshotKey ?? null,
  fingerprint: r.fingerprint ? r.fingerprint.current : null,
  snapshotValid: r.snapshotValid ?? null,
}));

const fnv = (str) => { let h = 0x811c9dc5; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); };
const checksum = fnv(JSON.stringify({ runId: cfg.runId, competitors, write: write && { mode: write.writeMode, n: write.recordsWritten } }));

const audit = {
  runId: cfg.runId,
  workflow: 'n8n-apify-hubspot-competitor-pricing-page-diff-tracker',
  status,
  mode: cfg.modeLabel,
  isoWeek: cfg.isoWeek,
  startedAt: cfg.runStartedAt,
  finishedAt: finishedAt.toISOString(),
  durationMs: Math.max(0, finishedAt - startedAt),
  safety: {
    sandboxRequested: cfg.sandboxRequested,
    sandboxMode: cfg.sandboxMode,
    dryRun: cfg.dryRun,
    hubspotLoggingEnabled: cfg.hubspotLoggingEnabled,
    sendSlackAlerts: cfg.sendSlackAlerts,
    sendOpsAlerts: cfg.sendOpsAlerts,
    gates: { allowHubspotWrite: cfg.allowHubspotWrite, allowSlackSend: cfg.allowSlackSend, allowOpsAlert: cfg.allowOpsAlert },
    envAccessible: cfg.envAccessible,
    secretsPresent: cfg.secretsPresent,
  },
  thresholds: engine.thresholds,
  stats: engine.stats,
  competitors,
  hubspot: write ? {
    mode: write.writeMode,
    objectType: cfg.hubspotObjectType,
    portalId: cfg.hubspotPortalId,
    recordsWritten: write.recordsWritten || 0,
    recordsPrepared: engine.stats.recordsPrepared,
    blockedReason: write.blockedReason || null,
    failures: (write.failures || []).length,
  } : null,
  slack,
  warnings,
  errors,
  checksum: `fnv1a-${checksum}`,
};

const needsOpsAlert = cfg.allowOpsAlert === true && (errors.length > 0 || competitors.some((c) => c.status === 'review_required'));

return [{
  json: {
    ...audit,
    needsOpsAlert,
    opsAlertPayload: needsOpsAlert ? {
      text: `[${cfg.modeLabel}] Competitor pricing tracker ${status} (${cfg.runId}): ${errors.length} error(s), ${warnings.length} warning(s).`,
      runId: cfg.runId,
      status,
      errors: errors.slice(0, 20),
      warnings: warnings.slice(0, 20),
    } : null,
  },
}];
